UPDATE questionnaires SET definition = '{"slug": "sf-background", "name": "About you", "questionnaire_type": "composable", "instructions": "A few questions about you, including any regular meditation, yoga, or other mind-body practice. None of your answers affect whether you take part.", "pages": [{"id": "bg_about", "components": [{"id": "bg_age", "type": "multiple_choice", "question": "What is your age?", "options": [{"id": "age", "label": "My age in years", "response_type": "number", "min": 18, "max": 100, "value": "age"}, {"id": "prefer_not", "label": "Prefer not to answer", "value": "prefer_not"}], "required": true, "allow_pna": false}, {"id": "bg_gender", "type": "multiple_choice", "question": "What is your gender?", "options": [{"id": "man", "label": "Man", "value": "man"}, {"id": "woman", "label": "Woman", "value": "woman"}, {"id": "non_binary", "label": "Non-binary", "value": "non_binary"}, {"id": "self_describe", "label": "Prefer to self-describe", "response_type": "text", "value": "self_describe"}, {"id": "prefer_not", "label": "Prefer not to say", "value": "prefer_not"}], "required": true, "allow_pna": false}, {"id": "bg_race", "type": "multiple_choice", "question": "What is your race/ethnicity? Select all that apply.", "options": [{"id": "east_asian", "label": "East Asian", "value": "east_asian"}, {"id": "south_asian", "label": "South Asian", "value": "south_asian"}, {"id": "southeast_asian", "label": "Southeast Asian", "value": "southeast_asian"}, {"id": "black", "label": "Black", "value": "black"}, {"id": "hispanic_latin", "label": "Hispanic or Latino/a/x", "value": "hispanic_latin"}, {"id": "indigenous", "label": "Indigenous (e.g., First Nations, Native American, Aboriginal and Torres Strait Islander, Māori)", "value": "indigenous"}, {"id": "mena", "label": "Middle Eastern or North African", "value": "mena"}, {"id": "pacific", "label": "Pacific Islander", "value": "pacific"}, {"id": "white", "label": "White", "value": "white"}, {"id": "mixed", "label": "Mixed or multiple", "value": "mixed"}, {"id": "other", "label": "Other (please specify)", "response_type": "text", "value": "other"}, {"id": "prefer_not", "label": "Prefer not to say", "exclusive": true, "value": "prefer_not"}], "required": true, "allow_pna": false, "allow_multiple": true}, {"id": "bg_country", "type": "multiple_choice", "question": "What is your current country of residence?", "options": [{"id": "us", "label": "United States", "value": "us"}, {"id": "uk", "label": "United Kingdom", "value": "uk"}, {"id": "ca", "label": "Canada", "value": "ca"}, {"id": "au", "label": "Australia", "value": "au"}, {"id": "ie", "label": "Ireland", "value": "ie"}, {"id": "nz", "label": "New Zealand", "value": "nz"}, {"id": "other", "label": "Other (please specify)", "response_type": "text", "value": "other"}], "required": true, "allow_pna": true}, {"id": "bg_education", "type": "multiple_choice", "question": "What is the highest level of education you have completed?", "options": [{"id": "lt_hs", "label": "Less than high school", "value": "lt_hs"}, {"id": "hs", "label": "High school or equivalent", "value": "hs"}, {"id": "some_college", "label": "Some college", "value": "some_college"}, {"id": "bachelors", "label": "Bachelor’s degree", "value": "bachelors"}, {"id": "graduate", "label": "Graduate or professional degree", "value": "graduate"}, {"id": "prefer_not", "label": "Prefer not to say", "value": "prefer_not"}], "required": true, "allow_pna": false}]}, {"id": "bg_practice", "components": [{"id": "bg_practice_regular", "type": "multiple_choice", "question": "Have you ever practiced meditation, yoga, or another contemplative or mind-body practice regularly (i.e., at least once a week for a period of two months or more)?", "options": [{"id": "yes", "label": "Yes", "value": "yes"}, {"id": "no", "label": "No", "value": "no"}], "required": true, "allow_pna": true}]}, {"id": "bg_practice_detail", "components": [{"id": "bg_practice_types", "type": "multiple_choice", "question": "Which practice(s) have you engaged in regularly? Select all that apply.", "options": [{"id": "meditation", "label": "Meditation (e.g., mindfulness, focused attention, loving-kindness)", "value": "meditation"}, {"id": "yoga", "label": "Yoga", "value": "yoga"}, {"id": "taichi_qigong", "label": "Tai chi / Qigong", "value": "taichi_qigong"}, {"id": "contemplative_prayer", "label": "Contemplative prayer or religious contemplative practice", "value": "contemplative_prayer"}, {"id": "martial_arts", "label": "Martial arts with a contemplative/meditative component", "value": "martial_arts"}, {"id": "other", "label": "Other", "response_type": "text", "value": "other"}], "required": true, "allow_pna": true, "allow_multiple": true, "show_if": {"component": "bg_practice_regular", "equals": "yes"}}, {"id": "bg_practice_years", "type": "multiple_choice", "question": "In total, for how many years have you practiced regularly (across all practices listed above)?", "options": [{"id": "years", "label": "Years", "response_type": "number", "min": 0, "max": 90, "value": "years"}, {"id": "prefer_not", "label": "Prefer not to answer", "value": "prefer_not"}], "required": true, "allow_pna": false, "show_if": {"component": "bg_practice_regular", "equals": "yes"}}, {"id": "bg_practice_freq", "type": "multiple_choice", "question": "Over the past 3 months, how often have you practiced?", "options": [{"id": "none", "label": "Not at all", "value": "none"}, {"id": "lt_weekly", "label": "Less than once a week", "value": "lt_weekly"}, {"id": "1_2_week", "label": "1–2 times a week", "value": "1_2_week"}, {"id": "3_5_week", "label": "3–5 times a week", "value": "3_5_week"}, {"id": "daily", "label": "Daily or near-daily", "value": "daily"}], "required": true, "allow_pna": true, "show_if": {"component": "bg_practice_regular", "equals": "yes"}}, {"id": "bg_practice_training", "type": "multiple_choice", "question": "Have you ever completed a formal, teacher-led training or program in a contemplative practice (e.g., an MBSR course, a yoga teacher training, a meditation retreat)?", "options": [{"id": "yes", "label": "Yes", "value": "yes"}, {"id": "no", "label": "No", "value": "no"}], "required": true, "allow_pna": true, "show_if": {"component": "bg_practice_regular", "equals": "yes"}}]}, {"id": "bg_spirit", "components": [{"id": "bg_religious", "type": "likert", "question": "To what extent do you consider yourself a religious person?", "scale": [{"value": 1, "label": "1 Not at all religious"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Very religious"}], "required": true, "allow_pna": true}, {"id": "bg_spiritual", "type": "likert", "question": "To what extent do you consider yourself a spiritual person?", "scale": [{"value": 1, "label": "1 Not at all spiritual"}, {"value": 2, "label": "2"}, {"value": 3, "label": "3"}, {"value": 4, "label": "4"}, {"value": 5, "label": "5 Very spiritual"}], "required": true, "allow_pna": true}, {"id": "bg_tradition", "type": "multiple_choice", "question": "Do you currently identify with a religious or spiritual tradition? Select the one that best applies.", "options": [{"id": "none", "label": "No religious/spiritual affiliation", "value": "none"}, {"id": "christian", "label": "Christian", "value": "christian"}, {"id": "muslim", "label": "Muslim", "value": "muslim"}, {"id": "jewish", "label": "Jewish", "value": "jewish"}, {"id": "buddhist", "label": "Buddhist", "value": "buddhist"}, {"id": "hindu", "label": "Hindu", "value": "hindu"}, {"id": "sikh", "label": "Sikh", "value": "sikh"}, {"id": "sbnr", "label": "Spiritual but not religious (unaffiliated)", "value": "sbnr"}, {"id": "other", "label": "Other", "response_type": "text", "value": "other"}, {"id": "prefer_not", "label": "Prefer not to say", "value": "prefer_not"}], "required": true, "allow_pna": false}]}]}'::jsonb, name = 'About you', updated_at = now() WHERE slug = 'sf-background';
UPDATE questionnaires SET definition = '{"slug": "sf-sfs", "name": "How you pay attention", "questionnaire_type": "composable", "instructions": "People pay attention in two ways. In the sensing mode, you take in what is here through your senses (sounds, textures, light, your breath) without needing to do anything with it. In the doing mode, you use what you know to plan, solve, judge, fix or get something done. Both are useful. These questions ask how you move between them.\n\nPlease rate how much you feel that each statement describes you right now, on a scale of 1-6.", "pages": [{"id": "sfs_p1", "components": [{"id": "sfs_01", "type": "likert", "question": "I feel confident in my ability to move into the sensing mode", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfs_03", "type": "likert", "question": "For me, the sensing mode feels different in kind from the doing mode of planning, fixing, and achieving", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfs_25", "type": "likert", "question": "Time in the sensing mode leaves me with a sense of awe or wonder", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfs_22", "type": "likert", "question": "I am more able to move into the sensing mode when I feel safe and secure", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfs_18", "type": "likert", "question": "I place extra value on returning to the sensing mode in moments when stress is pulling me toward narrow, familiar responses", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfs_27", "type": "likert", "question": "I look forward to the feeling that comes from sensory exploration, not just the skill of doing it", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfs_07", "type": "likert", "question": "Once I notice I have slipped into the doing mode without meaning to, I know how to shift back", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfs_05", "type": "likert", "question": "I see myself as having two gears that I can choose between: sensing and doing", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfs_24", "type": "likert", "question": "I can sense when my surroundings feel safe enough to explore openly", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}]}, {"id": "sfs_p2", "components": [{"id": "sfs_16", "type": "likert", "question": "Even when I am stressed, I try to make space for the sensing mode", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfs_21", "type": "likert", "question": "I can let a sensation simply be, without figuring out what it means or where it leads", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfs_26", "type": "likert", "question": "Engaging my senses fully opens up new ideas or perspectives I would not have noticed otherwise", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfs_09", "type": "likert", "question": "Moving into the sensing mode has gotten easier for me over time, even outside formal practice", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfs_12", "type": "likert", "question": "Returning to the sensing mode feels worth prioritizing, even when I am busy", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfs_23", "type": "likert", "question": "I notice that feeling unsafe or threatened makes it harder for me to stay open to my senses", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfs_attn_disagree", "type": "likert", "question": "To show that you are reading each statement, please select Disagree for this one.", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true}, {"id": "sfs_31", "type": "likert", "question": "Seeing something from a new or unexpected perspective feels valuable to me in its own right", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfs_04", "type": "likert", "question": "I can see clearly how easily the doing mode can become my default", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}]}, {"id": "sfs_p3", "components": [{"id": "sfs_11", "type": "likert", "question": "I place real value on time spent in the sensing mode, not only on getting things done", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfs_17", "type": "likert", "question": "I do not view it as a personal failing when stress narrows my attention. I recognize it as a natural response", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfs_30", "type": "likert", "question": "I enjoy the process of discovering something new, not just the outcome of what I find", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfs_08", "type": "likert", "question": "I can move into the sensing mode in unfamiliar or new settings, not just when I set time aside to practise", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfs_19", "type": "likert", "question": "I can experience a sensation without needing to judge it as good or bad", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfs_28", "type": "likert", "question": "I welcome surprise when I am in the sensing mode, rather than trying to predict or control what happens", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfs_13", "type": "likert", "question": "I notice quickly when I have drifted into autopilot or the doing mode without meaning to", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfs_20", "type": "likert", "question": "What I notice in the moment feels complete on its own, without needing to add meaning to it", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}]}, {"id": "sfs_p4", "components": [{"id": "sfs_06", "type": "likert", "question": "I can move into the sensing mode even in the middle of a stressful or demanding moment", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfs_10", "type": "likert", "question": "I realize I always have a choice between the sensing mode and the doing mode", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfs_02", "type": "likert", "question": "I recognize that the sensing mode is always available to me", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfs_attn_agree", "type": "likert", "question": "To show that you are reading each statement, please select Agree for this one.", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true}, {"id": "sfs_29", "type": "likert", "question": "I value being free from the need to have control or know what comes next", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfs_14", "type": "likert", "question": "I can tell the difference between a moment that calls for the doing mode and one that calls for the sensing mode", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfs_15", "type": "likert", "question": "I understand that stress and threat naturally pull people toward familiar ways of doing rather than open exploration", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}, {"id": "sfs_32", "type": "likert", "question": "I am drawn to uncertainty and ambiguity, not just tolerant of it, when I am in the sensing mode", "scale": [{"value": 1, "label": "Strongly disagree"}, {"value": 2, "label": "Disagree"}, {"value": 3, "label": "Mildly disagree"}, {"value": 4, "label": "Mildly agree"}, {"value": 5, "label": "Agree"}, {"value": 6, "label": "Strongly agree"}], "required": true, "allow_pna": true}]}], "interleave": {"items": ["sfs_01", "sfs_02", "sfs_03", "sfs_04", "sfs_05", "sfs_06", "sfs_07", "sfs_08", "sfs_09", "sfs_10", "sfs_11", "sfs_12", "sfs_13", "sfs_14", "sfs_15", "sfs_16", "sfs_17", "sfs_18", "sfs_19", "sfs_20", "sfs_21", "sfs_22", "sfs_23", "sfs_24", "sfs_25", "sfs_26", "sfs_27", "sfs_28", "sfs_29", "sfs_30", "sfs_31", "sfs_32", "sfs_attn_disagree", "sfs_attn_agree"], "page_sizes": [9, 9, 8, 8], "clusters": {"action": ["sfs_01", "sfs_06", "sfs_07", "sfs_08", "sfs_09"], "practice": ["sfs_02", "sfs_03"], "drift": ["sfs_04", "sfs_13", "sfs_14"], "view_core": ["sfs_05", "sfs_10", "sfs_11", "sfs_12"], "view_stress": ["sfs_16", "sfs_18"], "normalizing": ["sfs_15", "sfs_17"], "completeness": ["sfs_19", "sfs_20", "sfs_21"], "safety": ["sfs_22", "sfs_23", "sfs_24"], "reward": ["sfs_25", "sfs_26", "sfs_27"], "view_openness": ["sfs_28", "sfs_29", "sfs_30", "sfs_31", "sfs_32"]}, "cluster_min_gap": 3, "cluster_max_per_page": 2, "groups": [{"items": ["sfs_05", "sfs_10", "sfs_11", "sfs_12", "sfs_16", "sfs_18", "sfs_28", "sfs_29", "sfs_30", "sfs_31", "sfs_32"], "min_gap": 2, "max_per_page": 3}], "pairs": [["sfs_04", "sfs_13"], ["sfs_16", "sfs_18"], ["sfs_01", "sfs_09"], ["sfs_06", "sfs_16"]], "pair_min_gap": 3, "anchored": {"sfs_attn_disagree": {"min_position": 3, "max_position": 16, "not_page_edge": true}, "sfs_attn_agree": {"min_position": 20, "max_position": 33, "not_page_edge": true}}}}'::jsonb, name = 'How you pay attention', updated_at = now() WHERE slug = 'sf-sfs';
COMMIT;